import CryptoKit
import Foundation
import XCTest

@testable import OpenMedKit

/// Replays `tests/fixtures/parity/date_shift_v1.json`, generated by Python's
/// `openmed.core.date_shift`, through ``OpenMedDateShift``.
final class DateShiftParityTests: XCTestCase {
    func testPatientKeyOffsetsMatchPython() throws {
        let fixture = try loadFixture()
        let secrets = try testSecrets(fixture)
        let vectors = try XCTUnwrap(fixture["patient_key_offsets"] as? [[String: Any]])
        XCTAssertFalse(vectors.isEmpty)

        for vector in vectors {
            let id = try XCTUnwrap(vector["id"] as? String)
            let key = try XCTUnwrap(vector["patient_key"] as? String, id)
            let secret = try XCTUnwrap(secrets[try XCTUnwrap(vector["secret_id"] as? String, id)], id)
            let maxDays = try XCTUnwrap(vector["max_days"] as? Int, id)
            let expected = try XCTUnwrap(vector["offset_days"] as? Int, id)

            let digest = HMAC<SHA256>.authenticationCode(for: Data(key.utf8), using: SymmetricKey(data: secret))
            XCTAssertEqual(hex(Data(digest)), vector["digest_sha256_hex"] as? String, id)
            XCTAssertEqual(try OpenMedDateShift.stableOffset(patientKey: key, secret: secret, maxDays: maxDays), expected, id)
            XCTAssertEqual(
                try OpenMedDateShift.stableOffset(patientKey: Data(key.utf8), secret: secret, maxDays: maxDays), expected, id)
            if let text = String(data: secret, encoding: .utf8) {
                XCTAssertEqual(try OpenMedDateShift.stableOffset(patientKey: key, secret: text, maxDays: maxDays), expected, id)
            }
        }
    }

    func testSeedOffsetsMatchPythonInsideAndOutsideTheIntRange() throws {
        let fixture = try loadFixture()
        let vectors = try XCTUnwrap(fixture["seed_offsets"] as? [[String: Any]])
        XCTAssertFalse(vectors.isEmpty)
        var outsideInt = 0

        for vector in vectors {
            let id = try XCTUnwrap(vector["id"] as? String)
            let decimal = try XCTUnwrap(vector["seed_decimal"] as? String, id)
            let maxDays = try XCTUnwrap(vector["max_days"] as? Int, id)
            let expected = try XCTUnwrap(vector["offset_days"] as? Int, id)

            let digest = SHA256.hash(data: OpenMedDateShift.seedDomain + Data(decimal.utf8))
            XCTAssertEqual(hex(Data(digest)), vector["digest_sha256_hex"] as? String, id)
            XCTAssertEqual(try OpenMedDateShift.stableOffset(seedDecimal: decimal, maxDays: maxDays), expected, id)
            if let seed = Int(decimal) {
                XCTAssertEqual(try OpenMedDateShift.stableOffset(seed: seed, maxDays: maxDays), expected, id)
            } else {
                outsideInt += 1
            }
        }
        XCTAssertGreaterThan(outsideInt, 0)
    }

    func testShiftedDatesMatchPython() throws {
        let fixture = try loadFixture()
        let secrets = try testSecrets(fixture)
        let vectors = try XCTUnwrap(fixture["date_shifts"] as? [[String: Any]])
        XCTAssertFalse(vectors.isEmpty)

        for vector in vectors {
            let id = try XCTUnwrap(vector["id"] as? String)
            let maxDays = try XCTUnwrap(vector["max_days"] as? Int, id)
            let expected = try XCTUnwrap(vector["offset_days"] as? Int, id)
            let offset: Int
            if let key = vector["patient_key"] as? String {
                let secret = try XCTUnwrap(secrets[try XCTUnwrap(vector["secret_id"] as? String, id)], id)
                offset = try OpenMedDateShift.stableOffset(patientKey: key, secret: secret, maxDays: maxDays)
            } else {
                let decimal = try XCTUnwrap(vector["seed_decimal"] as? String, id)
                offset = try OpenMedDateShift.stableOffset(seedDecimal: decimal, maxDays: maxDays)
            }
            XCTAssertEqual(offset, expected, id)

            let source = try XCTUnwrap(vector["source_date"] as? String, id)
            let shifted = try XCTUnwrap(vector["shifted_date"] as? String, id)
            XCTAssertEqual(try OpenMedDateShift.shift(isoDate: source, byDays: offset), shifted, id)
            XCTAssertEqual(try OpenMedDateShift.shift(isoDate: shifted, byDays: -offset), source, id)
        }
    }

    func testEveryMaxDaysValueIsCoveredAndOffsetsStayInRange() throws {
        let fixture = try loadFixture()
        let values = try XCTUnwrap(fixture["max_days_values"] as? [Int])
        let used = Set(
            try XCTUnwrap(fixture["patient_key_offsets"] as? [[String: Any]]).compactMap { $0["max_days"] as? Int })
        XCTAssertEqual(Set(values), used)
        for maxDays in values + [2, OpenMedDateShift.maximumMaxDays] {
            var seen: Set<Int> = []
            for seed in -40...40 {
                let offset = try OpenMedDateShift.stableOffset(seed: seed, maxDays: maxDays)
                XCTAssertNotEqual(offset, 0)
                XCTAssertTrue((-maxDays...maxDays).contains(offset))
                seen.insert(offset)
            }
            if maxDays == 1 { XCTAssertEqual(seen, [-1, 1]) }
        }
    }

    func testProlepticGregorianArithmeticAndBounds() throws {
        let cases: [(String, Int, String)] = [
            ("1970-01-01", 0, "1970-01-01"),
            ("1970-01-01", -1, "1969-12-31"),
            ("2000-02-28", 1, "2000-02-29"),
            ("1900-02-28", 1, "1900-03-01"),
            ("1582-10-04", 1, "1582-10-05"),
            ("0001-01-01", 0, "0001-01-01"),
            ("0001-01-01", 3_652_058, "9999-12-31"),
            ("9999-12-31", -3_652_058, "0001-01-01"),
        ]
        for (source, days, expected) in cases {
            XCTAssertEqual(try OpenMedDateShift.shift(isoDate: source, byDays: days), expected, source)
        }
        for (source, days) in [("9999-12-31", 1), ("0001-01-01", -1), ("2024-01-01", Int.max), ("2024-01-01", Int.min)] {
            XCTAssertThrowsError(try OpenMedDateShift.shift(isoDate: source, byDays: days)) {
                XCTAssertEqual($0 as? OpenMedDateShiftError, .dateOutOfRange)
            }
        }
    }

    func testInvalidInputsThrowValueFreeErrors() throws {
        let secret = "SYNTHETIC_PRIVATE_SECRET_5414"
        let key = "SYNTHETIC-PATIENT-SENTINEL-5414"
        let checks: [(() throws -> Any, OpenMedDateShiftError)] = [
            ({ try OpenMedDateShift.stableOffset(patientKey: "", secret: secret, maxDays: 30) }, .patientKeyEmpty),
            ({ try OpenMedDateShift.stableOffset(patientKey: key, secret: "", maxDays: 30) }, .secretEmpty),
            ({ try OpenMedDateShift.stableOffset(patientKey: key, secret: Data(), maxDays: 30) }, .secretEmpty),
            ({ try OpenMedDateShift.stableOffset(patientKey: key, secret: secret, maxDays: 0) }, .maxDaysInvalid),
            ({ try OpenMedDateShift.stableOffset(patientKey: key, secret: secret, maxDays: -7) }, .maxDaysInvalid),
            ({ try OpenMedDateShift.stableOffset(patientKey: "", secret: "", maxDays: 0) }, .maxDaysInvalid),
            ({ try OpenMedDateShift.stableOffset(seed: 7, maxDays: Int.max) }, .maxDaysInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "-0", maxDays: 30) }, .seedInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "007", maxDays: 30) }, .seedInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "+7", maxDays: 30) }, .seedInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "7.0", maxDays: 30) }, .seedInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "", maxDays: 30) }, .seedInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "-", maxDays: 30) }, .seedInvalid),
            ({ try OpenMedDateShift.stableOffset(seedDecimal: "٣", maxDays: 30) }, .seedInvalid),
        ]
        for (index, (run, expected)) in checks.enumerated() {
            XCTAssertThrowsError(try run(), "check \(index)") { error in
                XCTAssertEqual(error as? OpenMedDateShiftError, expected, "check \(index)")
                self.assertValueFree(error, [secret, key])
            }
        }
        let dates = [
            "2023-02-29", "2024-13-01", "2024-00-10", "2024-04-31", "0000-01-01", "24-01-01", "2024-1-01",
            "2024/01/01", "2024-01-01T00:00", "２０２４-01-01", "",
        ]
        for date in dates {
            XCTAssertThrowsError(try OpenMedDateShift.shift(isoDate: date, byDays: 1), date) { error in
                XCTAssertEqual(error as? OpenMedDateShiftError, .dateInvalid, date)
                if !date.isEmpty { self.assertValueFree(error, [date]) }
            }
        }
        XCTAssertEqual(OpenMedDateShiftError.allCases.map(\.localizedDescription), OpenMedDateShiftError.allCases.map(\.rawValue))
    }

    // MARK: - Helpers

    private func assertValueFree(_ error: any Error, _ values: [String], file: StaticString = #filePath, line: UInt = #line) {
        let renderings = [
            String(describing: error), String(reflecting: error), error.localizedDescription, (error as NSError).description,
        ]
        for text in renderings {
            for value in values where text.contains(value) {
                XCTFail("an error rendering echoes an input", file: file, line: line)
            }
        }
    }

    private func testSecrets(_ fixture: [String: Any]) throws -> [String: Data] {
        var result: [String: Data] = [:]
        for secret in try XCTUnwrap(fixture["secrets"] as? [[String: Any]]) {
            XCTAssertEqual(secret["test_only"] as? Bool, true)
            let id = try XCTUnwrap(secret["id"] as? String)
            let data = try XCTUnwrap(bytes(hex: try XCTUnwrap(secret["hex"] as? String, id)), id)
            if let text = secret["utf8"] as? String { XCTAssertEqual(Data(text.utf8), data, id) }
            result[id] = data
        }
        return result
    }

    private func bytes(hex: String) -> Data? {
        let digits = Array(hex.utf8)
        guard digits.count.isMultiple(of: 2) else { return nil }
        var data = Data()
        for index in stride(from: 0, to: digits.count, by: 2) {
            guard let byte = UInt8(String(decoding: digits[index..<index + 2], as: UTF8.self), radix: 16) else { return nil }
            data.append(byte)
        }
        return data
    }

    private func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }

    private func loadFixture() throws -> [String: Any] {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { root.deleteLastPathComponent() }
        let data = try Data(contentsOf: root.appending(path: "tests/fixtures/parity/date_shift_v1.json"))
        let fixture = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertEqual(fixture["synthetic_only"] as? Bool, true)
        XCTAssertEqual(fixture["version"] as? Int, 1)
        return fixture
    }
}
